for (auto it = open_list.begin(); it != open_list.end(); ++it) {
    if ((*it)->f_value < lowest_f) {
        lowest_f = (*it)->f_value;
        lowest_node = *it;
    }
}
if (lowest_node != nullptr) {
    open_list.erase(std::remove(open_list.begin(), open_list.end(), lowest_node), open_list.end());
}
return lowest_node;

